#[inline]
fn destack_ipc_unix_receive_replay(
    binding: &BindingCallContext,
    world: RuntimeWorld,
    out: *mut UnixReceiveAncillary,
    socket: resource::SocketHandle,
    maxhandles: u32,
) -> RuntimeResult<()> {
    let _ = (&socket, &maxhandles);

    binding.trace().run_binding_without_context(
        IPC_UNIX_RECEIVE,
        binding.replay_payload_for(IPC_UNIX_RECEIVE)?,
        || match world {
            RuntimeWorld::Host => unsafe {
                platform_native::destack_ipc_unix_receive(binding, out, socket, maxhandles)
            },
            RuntimeWorld::Simulation => unsafe {
                platform_simulation_native::destack_ipc_unix_receive(
                    binding, out, socket, maxhandles,
                )
            },
        },
        |result| {
            if let Ok(()) = result {
                let result_value: UnixReceiveAncillary = unsafe { out.read() };
                let result_recorded_bytes = result_value.bytes;
                let result_recorded_handles_slice = unsafe { result_value.handles.as_slice()? };
                let mut result_recorded_handles =
                    Vec::with_capacity(result_recorded_handles_slice.len());
                for result_recorded_handles_item in result_recorded_handles_slice.iter().cloned() {
                    let result_recorded_handles_item_recorded = result_recorded_handles_item;
                    result_recorded_handles.push(result_recorded_handles_item_recorded);
                }
                let result_recorded_credentials = if let Some(value) = result_value.credentials {
                    let result_recorded_credentials_inner_pid = if let Some(value) = value.pid {
                        let result_recorded_credentials_inner_pid_inner = value;
                        Some(result_recorded_credentials_inner_pid_inner)
                    } else {
                        None
                    };
                    let result_recorded_credentials_inner_uid = value.uid;
                    let result_recorded_credentials_inner_gid = value.gid;
                    let result_recorded_credentials_inner = UnixPeerCredentials {
                        pid: result_recorded_credentials_inner_pid,
                        uid: result_recorded_credentials_inner_uid,
                        gid: result_recorded_credentials_inner_gid,
                    };
                    Some(result_recorded_credentials_inner)
                } else {
                    None
                };
                let result_recorded = UnixreceiveancillaryReplayRecord {
                    bytes: result_recorded_bytes,
                    handles: result_recorded_handles,
                    credentials: result_recorded_credentials,
                };
                let payload = IpcUnixReceiveReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    IpcUnixReceiveReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let value_native_bytes = value.bytes;
                    let value_native_handles = binding.store_array_with(
                        value.handles.len(),
                        |value_native_handles_values| {
                            for value_native_handles_item in value.handles {
                                let value_native_handles_decoded = value_native_handles_item;
                                value_native_handles_values.push(value_native_handles_decoded);
                            }
                            Ok(())
                        },
                    )?;
                    let value_native_credentials = if let Some(value) = value.credentials {
                        let value_native_credentials_inner_pid = if let Some(value) = value.pid {
                            let value_native_credentials_inner_pid_inner = value;
                            Some(value_native_credentials_inner_pid_inner)
                        } else {
                            None
                        };
                        let value_native_credentials_inner_uid = value.uid;
                        let value_native_credentials_inner_gid = value.gid;
                        let value_native_credentials_inner = UnixPeerCredentials {
                            pid: value_native_credentials_inner_pid,
                            uid: value_native_credentials_inner_uid,
                            gid: value_native_credentials_inner_gid,
                        };
                        Some(value_native_credentials_inner)
                    } else {
                        None
                    };
                    let value_native = UnixReceiveAncillary {
                        bytes: value_native_bytes,
                        handles: value_native_handles,
                        credentials: value_native_credentials,
                    };
                    unsafe { out.write(value_native) };
                    Ok(())
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    )
}

