/// VM replay implementations for ipc bindings.
#[inline]
fn destack_ipc_message_queue_close_vm_replay(
    binding: &BindingCallContext,
    context: &mut vm::ExternalCallContext<'_>,
    world: RuntimeWorld,
    handle: resource::MessageQueueHandle,
) -> RuntimeResult<vm::Word> {
    let result = binding.trace().run_binding(
        IPC_MESSAGE_QUEUE_CLOSE,
        binding.replay_payload_for(IPC_MESSAGE_QUEUE_CLOSE)?,
        context,
        |context| match world {
            RuntimeWorld::Host => {
                platform_vm::destack_ipc_message_queue_close(binding, context, handle)
            }
            RuntimeWorld::Simulation => {
                platform_simulation_vm::destack_ipc_message_queue_close(binding, context, handle)
            }
        },
        |_context, result| {
            if let Ok(()) = result {
                let result_recorded = ();
                let payload = IpcMessageQueueCloseReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    IpcMessageQueueCloseReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |_context, payload| {
            // replay result
            match payload.result {
                Ok(()) => Ok(()),
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    );
    let result = encode_destack_ipc_message_queue_close_result(context, result)?;
    Ok(result)
}

