#[inline]
fn destack_ipc_unix_receive_vm_replay(
    binding: &BindingCallContext,
    context: &mut vm::ExternalCallContext<'_>,
    world: RuntimeWorld,
    socket: resource::SocketHandle,
    maxhandles: u32,
) -> RuntimeResult<vm::Word> {
    let result = binding.trace().run_binding(
        IPC_UNIX_RECEIVE,
        binding.replay_payload_for(IPC_UNIX_RECEIVE)?,
        context,
        |context| match world {
            RuntimeWorld::Host => {
                platform_vm::destack_ipc_unix_receive(binding, context, socket, maxhandles)
            }
            RuntimeWorld::Simulation => platform_simulation_vm::destack_ipc_unix_receive(
                binding, context, socket, maxhandles,
            ),
        },
        |context, result| {
            let context = &context.read();
            if let Ok(value) = result {
                let result_value: UnixReceiveAncillaryVm = value.clone();
                let result_recorded_bytes = result_value.bytes;
                let result_recorded_handles_raw = result_value.handles.values(context)?;
                let mut result_recorded_handles =
                    Vec::with_capacity(result_recorded_handles_raw.len());
                for result_recorded_handles_item_value in result_recorded_handles_raw {
                    let result_recorded_handles_item_inner_inner = decode_uint64(
                        result_recorded_handles_item_value,
                        "result_recorded_handles_item_inner_inner",
                        "item",
                    )?;
                    let result_recorded_handles_item_inner =
                        resource::ResourceId(result_recorded_handles_item_inner_inner);
                    let result_recorded_handles_item =
                        resource::TransferredHandle(result_recorded_handles_item_inner);
                    let result_recorded_handles_item_recorded = result_recorded_handles_item;
                    result_recorded_handles.push(result_recorded_handles_item_recorded);
                }
                let result_recorded_credentials = if let Some(value) = result_value.credentials {
                    let result_recorded_credentials_inner_pid = if let Some(value) = value.pid {
                        let result_recorded_credentials_inner_pid_inner = value;
                        Some(result_recorded_credentials_inner_pid_inner)
                    } else {
                        None
                    };
                    let result_recorded_credentials_inner_uid = value.uid;
                    let result_recorded_credentials_inner_gid = value.gid;
                    let result_recorded_credentials_inner = UnixPeerCredentials {
                        pid: result_recorded_credentials_inner_pid,
                        uid: result_recorded_credentials_inner_uid,
                        gid: result_recorded_credentials_inner_gid,
                    };
                    Some(result_recorded_credentials_inner)
                } else {
                    None
                };
                let result_recorded = UnixreceiveancillaryReplayRecord {
                    bytes: result_recorded_bytes,
                    handles: result_recorded_handles,
                    credentials: result_recorded_credentials,
                };
                let payload = IpcUnixReceiveReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    IpcUnixReceiveReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |context, payload| {
            let context = &mut context.write();
            // replay result
            match payload.result {
                Ok(value) => {
                    let vm_result_bytes = value.bytes;
                    let mut vm_result_handles_builder =
                        VmArray::<resource::TransferredHandle>::builder(
                            context,
                            value.handles.len(),
                        )?;
                    for vm_result_handles_item in value.handles {
                        let vm_result_handles_item_value = vm_result_handles_item;
                        vm_result_handles_builder.push(context, vm_result_handles_item_value)?;
                    }
                    let vm_result_handles = vm_result_handles_builder.finish()?;
                    let vm_result_credentials = if let Some(value) = value.credentials {
                        let vm_result_credentials_inner_pid = if let Some(value) = value.pid {
                            let vm_result_credentials_inner_pid_inner = value;
                            Some(vm_result_credentials_inner_pid_inner)
                        } else {
                            None
                        };
                        let vm_result_credentials_inner_uid = value.uid;
                        let vm_result_credentials_inner_gid = value.gid;
                        let vm_result_credentials_inner = UnixPeerCredentials {
                            pid: vm_result_credentials_inner_pid,
                            uid: vm_result_credentials_inner_uid,
                            gid: vm_result_credentials_inner_gid,
                        };
                        Some(vm_result_credentials_inner)
                    } else {
                        None
                    };
                    let vm_result = UnixReceiveAncillaryVm {
                        bytes: vm_result_bytes,
                        handles: vm_result_handles,
                        credentials: vm_result_credentials,
                    };
                    Ok(vm_result)
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    );
    let result = encode_destack_ipc_unix_receive_result(context, result)?;
    Ok(result)
}

